package status

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/status"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

func (m Model) InEditMode() bool {
	return m.componentForm != nil || m.filterBar.InEditMode()
}

// FilterBarVisible returns true when the filter bar is visible (implements app.FilterBarView).
func (m Model) FilterBarVisible() bool {
	return m.filterBar.IsVisible() && m.componentForm == nil && m.confirmModal == nil && m.error == "" && len(m.components) > 0
}

func (m Model) GetShortcuts() shortcut.Shortcuts {
	// vue edition/ajout composant
	if m.componentForm != nil {
		return []shortcut.Shortcut{
			{Key: "esc", Description: "Cancel"},
			{Key: "enter", Description: "Submit"},
		}
	}

	// vue principale status
	return []shortcut.Shortcut{
		{Key: "ctrl+n", Description: "New monitor"},
		{Key: "e", Description: "Edit monitor"},
		{Key: "ctrl+d", Description: "Delete monitor"},
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: "±", Description: "Adjust interval"},
		{Key: "space", Description: "Pause/Resume"},
		{Key: "tab", Description: "Switch tab"},
		{Key: ".", Description: "Sort"},
		{Key: "/", Description: "Search"},
		{Key: "alt+:", Description: "Command mode"},
		{Key: "?", Description: "Help"},
	}
}

func (m Model) GetTitle() string {
	base := theme.IconService + " Status Monitor"
	if m.componentForm != nil {
		return base + " " + theme.IconChevronRight + " " + m.componentForm.GetTitle()
	}
	return base
}

func (m Model) GetIcon() string {
	return ""
}

// GetHeaderInfo returns the key-value info for the header
func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	return []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
		{Key: "Refresh", Value: fmt.Sprintf("%ds", int(m.refreshInterval.Seconds())), Style: theme.HeaderValueStyle},
	}
}

// View rend la vue
func (m Model) View() string {
	// Mode formulaire - overlay
	if m.componentForm != nil {
		return m.componentForm.View()
	}

	// Mode confirmation - overlay
	if m.confirmModal != nil {
		return lipgloss.Place(
			m.width,
			m.height,
			lipgloss.Center,
			lipgloss.Center,
			m.confirmModal.View(),
			lipgloss.WithWhitespaceBackground(theme.ColorBackground),
		)
	}

	// Content - HAUTEUR DYNAMIQUE qui remplit exactement l'espace disponible
	var innerContent string
	if m.error != "" {

		m.updateTable()
		m.getCurrentTable().GotoTop() // a narrowing query starts from the first match
		return m, cmd
	}

	// Mode formulaire - prioritaire
	if m.componentForm != nil {
		var cmd tea.Cmd
		m.componentForm, cmd = m.componentForm.Update(msg)
		return m, cmd
	}

	// Mode confirmation - prioritaire
	if m.confirmModal != nil {
		var cmd tea.Cmd
		m.confirmModal, cmd = m.confirmModal.Update(msg)
		return m, cmd
	}

	// Mode normal - déléguer selon le type de commande
	switch msg.String() {
	case "/":
		return m, m.filterBar.ActivateSearch()
	case "q", "ctrl+c":
		return m, tea.Quit
	case "ctrl+r", " ":
		return m.handleRefreshControls(msg)
	case "up", "down", "k", "j", "tab", "shift+tab", "g", "G", "home", "end":
		return m.handleTableNavigation(msg)
	case "ctrl+n", "e", "ctrl+d":
		return m.handleMonitorOperations(msg)
	case ".":
		return m.cycleSort()
	}

	return m, nil
}

// handleRefreshControls handles refresh, pause, and interval adjustments
func (m Model) handleRefreshControls(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "ctrl+r":
		// Refresh immédiat
		if !m.checking {
			m.checking = true
			return m, tea.Batch(
				m.spinner.Tick,
				checkComponents(m.config),
			)
		}

	case " ":
		// Toggle pause
		m.paused = !m.paused
		if !m.paused && !m.checking && time.Since(m.lastCheck) >= m.refreshInterval {
			m.checking = true
			return m, tea.Batch(
				m.spinner.Tick,
				checkComponents(m.config),
			)
		}

	}

	return m, nil
}

// switchTab switches focus to the given tab
func (m *Model) switchTab(tab int) {
	m.activeTab = tab
	m.applyTabFocus()
}

// handleTableNavigation handles up, down, and tab navigation
func (m Model) handleTableNavigation(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "up", "k", "down", "j", "pgup", "pgdown", "g", "home", "G", "end":
		return m, m.getCurrentTable().Update(msg)
	case "tab":
		m.switchTab((m.activeTab + 1) % 2)

