147	func (m Model) RenderFooter(width int) string {
148		if m.componentForm == nil && m.confirmModal == nil && m.error == "" && len(m.components) > 0 {
149			var parts []string
150			if m.filterBar.IsVisible() {
151				parts = append(parts, m.filterBar.View())
152			}
153			parts = append(parts,
154				theme.PadWithBg(theme.Bg(" ")+m.renderTabs(), width),
155				theme.EmptyLineBg(width),
156				theme.EmptyLineBg(width),
157			)
158			return strings.Join(parts, "\n")
159		}
160		return theme.EmptyLineBg(width) + "\n" + theme.EmptyLineBg(width)
161	}
