				Body:  "Monitors are saved in the active context configuration file (~/.devdesk/contexts/<context>/config.yaml). Refresh interval and auto-refresh are configurable.",
			},
		},
	}
}

// formatSSLStatus formate le statut pour les certificats SSL
func formatSSLStatus(comp status.ComponentStatus) string {
	switch comp.Status {
	case "OK":
		// return theme.StatusOKStyle.Render("✓ OK")
		return theme.IconOK
	case "WARNING":
		// warningStyle := lipgloss.NewStyle().Foreground(theme.ColorWarn).Bold(true)
		return theme.IconWarning
	case "ERROR":
		// return theme.StatusErrorStyle.Render("✗ ERROR")
		return theme.IconError
	case "DOWN":
		// return theme.StatusDownStyle.Render("✗ DOWN")
		return theme.IconError
	default:
		return string(comp.Status)
	}
}

// matchesQuery reports whether a component survives the text filter. Name,
// target and type, which is what the two loops this replaced matched between
// them — the SSL one left type out, and a `type:` query narrowing one table and
// not the other was never deliberate.
func matchesQuery(comp status.ComponentStatus, query string) bool {
	if query == "" {
		return true
	}
	return strings.Contains(strings.ToLower(comp.Name), query) ||
		strings.Contains(strings.ToLower(comp.Target), query) ||
		strings.Contains(strings.ToLower(string(comp.Type)), query)
}

